    if (!item.effective || removed.has(key(item.issuer, item.id))) continue;
    for (const id of Object.keys(item.payload).sort(cmp)) {
      const data = object(item.payload[id]);
      if (typeof data.type === "string") entries.push({ item, id, data });
    }
  }
